import React from 'react';
import { useAuth } from '../context/AuthContext';
import NotificationBell from '../Notifications/NotificationBell';
import ChatIcon from '../Chat/ChatIcon';

const Navbar = () => {
  const { user, logout } = useAuth();

  return (
    <nav className="bg-gradient-to-r from-blue-600 via-blue-700 to-indigo-800 border-b-2 border-blue-800 px-8 py-4 flex justify-between items-center sticky top-0 z-50 shadow-lg backdrop-blur-sm">
      <div className="flex items-center space-x-3">
        <div className="w-10 h-10 rounded-lg bg-white/20 flex items-center justify-center">
          <span className="text-white font-bold text-lg"></span>
        </div>
        <h1 className="text-2xl font-bold text-white tracking-tight">SOTACIB Workflow</h1>
      </div>
      <div className="flex items-center space-x-6">
        <div className="flex items-center space-x-4 border-r border-white/20 pr-6">
          <NotificationBell />
          <ChatIcon />
        </div>
        <div className="flex items-center space-x-3">
          <div className="text-right">
            <p className="text-white font-semibold text-sm">{user?.fullName}</p>
            <p className="text-blue-100 text-xs">{user?.role}</p>
          </div>
          <div className="w-10 h-10 rounded-full bg-blue-400/30 border-2 border-white/30 flex items-center justify-center text-white font-bold">
            {user?.fullName?.charAt(0).toUpperCase()}
          </div>
        </div>
        <button onClick={logout} className="btn btn-danger text-sm">Déconnexion</button>
      </div>
    </nav>
  );
};

export default Navbar;
